export type BatchStatus =
  | "queued"
  | "running"
  | "paused"
  | "done"
  | "cancelled";

export interface Batch {
  id: string;
  name: string;
  status: BatchStatus;
  totalCalls: number;
  completed: number;
  failed: number;
  inProgress: number;

  queued: number;
  cancelled: number;
  pickupRate: number | null;
  successRate: number | null;
  createdAt: string;
  cancelledBy?: string;
  cancelledAt?: string;
}

export const CURRENT_USER = "Omar Haddad";

export function settled(batch: Batch): number {
  return batch.completed + batch.failed + batch.cancelled;
}

export function cancelBatch(batch: Batch, at: string): Batch {
  return {
    ...batch,
    status: "cancelled",
    cancelled: batch.cancelled + batch.queued,
    queued: 0,
    cancelledBy: CURRENT_USER,
    cancelledAt: at,
  };
}

